cd /app/work; python3 -c "
from kin import *
import numpy as np
V2=[0,-0.3,0,0.9,0,1.999,0]
# upper segment
obs_p=[(10,64.5),(50,64),(100,64),(125,64.5)]
obs_2=[(5,263.5),(50,265),(100,265),(150,266)]
obs_pl=[(135,67.5),(450,69.5),(470,70.5)]
obs_2l=[(250,269.5),(350,271),(400,272),(425,272)]
def fit(op,o2):
  best=None
  for x0 in np.arange(0.38,0.47,0.0025):
   for z0 in np.arange(0.0,0.2,0.0025):
    for s in np.arange(-0.4,0.4,0.01):
      err=0
      for v,u in op:
        # find y with this v: iterate
        y=0
        for _ in range(5):
          z=z0+s*y; y=(v-239.5)/416*(0.389-z)
        uu=project(PARK,(x0,y,z0+s*y))[0]; err+=(uu-u)**2
      for v,u in o2:
        y=0
        for _ in range(8):
          z=z0+s*y; uu,vv,_=project(V2,(x0,y,z)); y+= (v-vv)*0.0015
        err+=(uu-u)**2
      if best is None or err<best[0]: best=(err,x0,z0,s)
  return best
print(fit(obs_p,obs_2)); print(fit(obs_pl,obs_2l))
"

