from trk import *
from kin import *
import numpy as np
V1=[0,0,0,1.2,0,1.94,0];V2=[0,-0.3,0,0.9,0,1.999,0];V3=[-0.7,-0.3,0,0.9,0,1.999,0]; V4=[-0.408,0.234,-0.429,1.474,-0.189,0.687,1.983]
views=[('park',PARK,(0,480),(0,200)),('v1',V1,(0,480),(40,200)),('v2',V2,(0,430),(200,320)),('v3',V3,(180,480),(60,420)),('v4',V4,(0,240),(200,480))]
rays=[]
for name,q,vr,ur in views:
    for v,a,b,uc in centers('../output/'+name+'.png',q,vr,ur,step=6):
        if b-a<15: continue
        C,w=ray2(q,uc,v); rays.append((name,C,w))
def linedist(C,w,P0,d):
    n=np.cross(w,d); nn=np.linalg.norm(n); return (P0-C)@n/nn
def resid(p,seg):
    x0,kx,z0,s=p; out=[]
    for name,C,w in seg:
        P0=np.array([x0,-0.075,z0]); d=np.array([kx,1,s]); d/=np.linalg.norm(d)
        out.append(linedist(C,w,P0,d))
    return np.array(out)
def gn(seg,p):
    p=np.array(p,float)
    for it in range(30):
        r=resid(p,seg); J=np.zeros((len(r),4))
        for i in range(4):
            dp=p.copy(); dp[i]+=1e-6; J[:,i]=(resid(dp,seg)-r)/1e-6
        p-=np.linalg.lstsq(J,r,rcond=None)[0]
    return p,resid(p,seg)
def segy(C,w):
    # y where ray crosses x=0.416
    t=(0.416-C[0])/w[0]; return (C+t*w)[1]
up=[r for r in rays if segy(r[1],r[2])<-0.085]; lo=[r for r in rays if segy(r[1],r[2])>-0.065]
for nm,seg in [('upper',up),('lower',lo)]:
    p,r=gn(seg,[0.416,0,0.11,-0.03])
    print(nm,np.round(p,4),'rms',np.sqrt(np.mean(r**2)))
    for vn in ['park','v1','v2','v3','v4']:
        rr=[ri for ri,s in zip(r,seg) if s[0]==vn]
        if rr: print('   ',vn,len(rr),np.round(np.mean(rr)*1000,2),np.round(np.std(rr)*1000,2))
