from ik import *
def hand_R(alpha):
    s,c=np.sin(alpha),np.cos(alpha)
    x=np.array([-1.,0,0]); y=np.array([0,c,-s]); z=np.array([0,-s,-c])
    return np.column_stack([x,y,z])
def catch_pose(xc,yc,zlow,alpha,q0,dz=0.0):
    R=hand_R(alpha)
    # lowest corner hand(0,0.012,0.07) at z=zlow; bar center hand(0,0,0.04) at y=yc
    low=R@np.array([0,0.012,0.07]); mid=R@np.array([0,0,0.04])
    palm=np.array([xc, yc-mid[1], zlow-low[2]+dz])
    q,e=ik(palm,R,q0,qref=q0,wref=0.05)
    return q,e,palm
def finger_pts(q,gap=0.06):
    H=hand(q); pts=[]
    for sx in (-1,1):
        for xh in (gap/2, gap/2+0.008):
            for yh in (-0.012,0.012):
                for zh in (0.01,0.07):
                    pts.append((H@np.array([sx*xh,yh,zh,1]))[:3])
    return np.array(pts)
