from catch import *
def body_pts(q):
    F=chain(q); pts=list(finger_pts(q))
    H=F[-1]
    for xh in (-0.03,0.03):
        for yh in (-0.02,0.02):
            for zh in (-0.01,0.01): pts.append((H@np.array([xh,yh,zh,1]))[:3])
    # forearm and wrist samples
    for a,b in [(F[1],F[2]),(F[2],F[3]),(F[0],F[1])]:
        for s in np.linspace(0,1,8): pts.append(a[:3,3]*(1-s)+b[:3,3]*s)
    return np.array(pts)
def min_track_clear(qa,qb,n=60,xr=(0.38,0.47),ztop=0.115):
    qa=np.asarray(qa,float);qb=np.asarray(qb,float); worst=9
    for s in np.linspace(0,1,n):
        P=body_pts(qa+(qb-qa)*s)
        near=(P[:,0]>xr[0])&(P[:,0]<xr[1])
        zmin=P[near,2].min() if near.any() else 9
        worst=min(worst,zmin-ztop, P[:,2].min())
    return worst
