from opt import *
ALPHA=1.0; YLOW=0.0376; CLR=0.003; XC=0.4316
def zwall(y): return 0.0866-0.045*(y-0.0376)
def cpose(alpha=ALPHA,clr=CLR,dz=0.0,q0=None,opt=True):
    palm,R=pose_target(XC,YLOW,zwall(YLOW)+clr+dz,alpha)
    if opt:
        m,q=null_opt(palm,R,q0 if q0 is not None else [0.58,0.94,-0.3,1.36,-0.73,1.39,0.69],PARK,iters=200)
    else:
        q,e=ik(palm,R,q0,iters=300)
    return q
def fingers_dense(q,gap=0.06):
    H=hand(q); pts=[]
    for sx in (-1,1):
        for xh in np.linspace(gap/2,gap/2+0.008,3):
            for yh in np.linspace(-0.012,0.012,5):
                for zh in np.linspace(0.01,0.07,7):
                    pts.append((H@np.array([sx*xh,yh,zh,1]))[:3])
    for xh in np.linspace(-0.03,0.03,5):
        for yh in np.linspace(-0.02,0.02,3):
            for zh in (-0.01,0.01): pts.append((H@np.array([xh,yh,zh,1]))[:3])
    return np.array(pts)
def wall_clear(q):
    P=fingers_dense(q)
    inx=(P[:,0]>XC-0.028-0.001)&(P[:,0]<XC+0.028+0.001)&(P[:,1]>-0.6)&(P[:,1]<0.28)
    if not inx.any(): return 9
    return np.min(P[inx,2]-zwall(P[inx,1]))
def path_wall_clear(qa,qb,n=200):
    qa=np.array(qa);qb=np.array(qb)
    return min(wall_clear(qa+(qb-qa)*s) for s in np.linspace(0,1,n))
