from final import *
q0=np.array([1.002,0.577,-1.463,1.295,0.879,1.999,2.454])
q1=np.array([1.8837,0.8835,-2.345,1.5502,0.9316,1.9308,2.454])
def pts(q):
    F=chain(q); Hm=F[-1]; P=[(Hm@np.array([sx*0.03,sy*0.02,z,1]))[:3] for sx in(-1,1) for sy in (-1,1) for z in (0,0.04,0.08)]
    for a,b in [(F[0],F[1]),(F[1],F[2]),(F[2],F[3])]:
        for s in np.linspace(0,1,6): P.append(a[:3,3]*(1-s)+b[:3,3]*s)
    return np.array(P)
m=9
for s in np.linspace(0,1,60):
    P=pts(q0+(q1-q0)*s); i=np.argmin(P[:,2]); 
    if P[i,2]<m: m=P[i,2]; arg=(s,np.round(P[i],3))
print(m,arg); print(np.round(hand(q1)[:3,3],3))
"

