cd /app/work; python3 -c "
from final import *
import json
R=np.column_stack([[0,1.,0],[1.,0,0],[0,0,-1.]])
q0=np.array([1.884,0.884,-2.345,1.55,0.932,1.931,2.454])
qa=np.array([1.6297,0.7941,-1.0396,1.4501,0.6938,1.293,2.103])
pts=[]; q=qa.copy()
for dz in np.linspace(0.10,0.0,6):
    q,e=ik(np.array([0.236,0.36,0.128+dz]),R,q,iters=300); assert e<1e-8; pts.append([float(x) for x in np.round(q,4)])
print(pts[0],pts[-1])
def low(q):
    F=chain(q); Hm=F[-1]; P=[(Hm@np.array([sx*0.03,sy*0.02,z,1]))[:3] for sx in(-1,1) for sy in (-1,1) for z in (0,0.04,0.082)]
    for a,b in [(F[0],F[1]),(F[1],F[2]),(F[2],F[3])]:
        for s in np.linspace(0,1,6): P.append(a[:3,3]*(1-s)+b[:3,3]*s)
    return np.array(P)
m=min(low(q0+(np.array(pts[0])-q0)*s)[:,2].min() for s in np.linspace(0,1,80)); print('min z to above',m)
print('T',np.max(np.abs(np.array(pts[0])-q0))/0.6)
json.dump(pts,open('down.json','w'))
# where are the fingers at the release
Hm=hand(np.array(pts[-1])); 
for p in [(0,0.009,0.068),(0.03,0,0.07),(-0.03,0,0.07)]: print(p,np.round((Hm@np.array([*p,1]))[:3],3))
"

