import json,numpy as np
from final import *
d=json.load(open('down.json')); up=d[::-1][1:]
json.dump(up,open('up2.json','w'))
qa=np.array(up[-1])
def low(q):
    F=chain(q); Hm=F[-1]; P=[(Hm@np.array([sx*0.038,sy*0.012,z,1]))[:3] for sx in(-1,1) for sy in (-1,1) for z in (0,0.07)]
    for a,b in [(F[0],F[1]),(F[1],F[2]),(F[2],F[3])]:
        for s in np.linspace(0,1,6): P.append(a[:3,3]*(1-s)+b[:3,3]*s)
    return np.array(P)
m=9
for s in np.linspace(0,1,100):
    P=low(qa+(PARK-qa)*s); i=np.argmin(P[:,2])
    if P[i,2]<m: m=P[i,2]; w=(s,np.round(P[i],3))
print(m,w)
"

